Value.Calculation:
JSONSetElement ( "{}" ;
  [ "id" ; WMPSES_试卷场景::pk_ExamID ; JSONString ] ;
  [ "title" ; WMPSES_试卷场景::Title ; JSONString ] ;
  [ "subtitle" ; WMPSES_试卷场景::Subtitle ; JSONString ] ;
  [ "examCode" ; WMPSES_试卷场景::ExamCode ; JSONString ] ;
  [ "totalScore" ; GetAsNumber ( WMPSES_试卷场景::TotalScore ) ; JSONNumber ] ;
  [ "passScore" ; GetAsNumber ( WMPSES_试卷场景::PassScore ) ; JSONNumber ] ;
  [ "durationMinutes" ; GetAsNumber ( WMPSES_试卷场景::DurationMinutes ) ; JSONNumber ] ;
  [ "version" ; WMPSES_试卷场景::Version ; JSONString ] ;
  [ "updatedAt" ; GetAsText ( WMPSES_试卷场景::UpdatedAt ) ; JSONString ]
)

Let ( [
  cnt = Count ( WMPSES_习题库::pk_QuestionID )
] ;
  While (
    [ i = 1 ; qArr = "[]" ] ;
    i ≤ cnt ;
    [
      optA = GetNthRecord ( WMPSES_习题库::OptionA ; i ) ;
      optB = GetNthRecord ( WMPSES_习题库::OptionB ; i ) ;
      optC = GetNthRecord ( WMPSES_习题库::OptionC ; i ) ;
      optD = GetNthRecord ( WMPSES_习题库::OptionD ; i ) ;
      optE = GetNthRecord ( WMPSES_习题库::OptionE ; i ) ;
      opts = "[]" ;
      oi = 0 ;
      opts = If ( not IsEmpty ( optA ) ; JSONSetElement ( opts ; ["[" & oi & "].key" ; "A" ; JSONString] ; ["[" & oi & "].text" ; optA ; JSONString] ) ; opts ) ;
      oi = If ( not IsEmpty ( optA ) ; oi + 1 ; oi ) ;
      opts = If ( not IsEmpty ( optB ) ; JSONSetElement ( opts ; ["[" & oi & "].key" ; "B" ; JSONString] ; ["[" & oi & "].text" ; optB ; JSONString] ) ; opts ) ;
      oi = If ( not IsEmpty ( optB ) ; oi + 1 ; oi ) ;
      opts = If ( not IsEmpty ( optC ) ; JSONSetElement ( opts ; ["[" & oi & "].key" ; "C" ; JSONString] ; ["[" & oi & "].text" ; optC ; JSONString] ) ; opts ) ;
      oi = If ( not IsEmpty ( optC ) ; oi + 1 ; oi ) ;
      opts = If ( not IsEmpty ( optD ) ; JSONSetElement ( opts ; ["[" & oi & "].key" ; "D" ; JSONString] ; ["[" & oi & "].text" ; optD ; JSONString] ) ; opts ) ;
      oi = If ( not IsEmpty ( optD ) ; oi + 1 ; oi ) ;
      opts = If ( not IsEmpty ( optE ) ; JSONSetElement ( opts ; ["[" & oi & "].key" ; "E" ; JSONString] ; ["[" & oi & "].text" ; optE ; JSONString] ) ; opts ) ;
      ansRaw = Substitute ( Trim ( GetNthRecord ( WMPSES_习题库::AnswerKeys ; i ) ) ; [ "，" ; "," ] ; [ " " ; "" ] ; [ "," ; ¶ ] ) ;
      ansCnt = ValueCount ( ansRaw ) ;
      ansArr = While (
        [ k = 1 ; a = "[]" ] ;
        k ≤ ansCnt ;
        [
          v = GetValue ( ansRaw ; k ) ;
          a = If ( not IsEmpty ( v ) ; JSONSetElement ( a ; "[" & (k - 1) & "]" ; v ; JSONString ) ; a ) ;
          k = k + 1
        ] ;
        a
      ) ;
      qObj = JSONSetElement ( "{}" ;
        [ "id" ; GetNthRecord ( WMPSES_习题库::pk_QuestionID ; i ) ; JSONString ] ;
        [ "defectCode" ; GetNthRecord ( WMPSES_习题库::DefectCode ; i ) ; JSONString ] ;
        [ "defectLevel" ; GetNthRecord ( WMPSES_习题库::DefectLevel ; i ) ; JSONString ] ;
        [ "isMajorDefect" ; GetAsBoolean ( GetNthRecord ( WMPSES_习题库::IsMajorDefect ; i ) ) ; JSONBoolean ] ;
        [ "isCriticalConclusion" ; GetAsBoolean ( GetNthRecord ( WMPSES_习题库::IsCriticalConclusion ; i ) ) ; JSONBoolean ] ;
        [ "type" ; GetNthRecord ( WMPSES_习题库::QuestionType ; i ) ; JSONString ] ;
        [ "score" ; GetAsNumber ( GetNthRecord ( WMPSES_习题库::Score ; i ) ) ; JSONNumber ] ;
        [ "title" ; GetNthRecord ( WMPSES_习题库::QuestionTitle ; i ) ; JSONString ] ;
        [ "options" ; opts ; JSONArray ] ;
        [ "answer" ; ansArr ; JSONArray ] ;
        [ "referenceStandard" ; GetNthRecord ( WMPSES_习题库::ReferenceStandard ; i ) ; JSONString ] ;
        [ "explanation" ; GetNthRecord ( WMPSES_习题库::Explanation ; i ) ; JSONString ]
      ) ;
      qArr = JSONSetElement ( qArr ; "[" & (i - 1) & "]" ; qObj ; JSONObject ) ;
      i = i + 1
    ] ;
    qArr
  )
)

JSONSetElement ( "{}" ;
  [ "id" ; WMPSES_设备热点::pk_HotspotID ; JSONString ] ;
  [ "order" ; GetAsNumber ( WMPSES_设备热点::SortOrder ) ; JSONNumber ] ;
  [ "code" ; WMPSES_设备热点::DeviceCode ; JSONString ] ;
  [ "name" ; WMPSES_设备热点::DeviceName ; JSONString ] ;
  [ "category" ; WMPSES_设备热点::Category ; JSONString ] ;
  [ "x" ; GetAsNumber ( WMPSES_设备热点::CoordX ) ; JSONNumber ] ;
  [ "y" ; GetAsNumber ( WMPSES_设备热点::CoordY ) ; JSONNumber ] ;
  [ "widgetType" ; WMPSES_设备热点::WidgetType ; JSONString ] ;
  [ "sceneSummary" ; WMPSES_设备热点::SceneSummary ; JSONString ] ;
  [ "questions" ; $qArr ; JSONArray ]
)
